import React, { useState } from 'react';

const QuizConfigPage = () => {
  const [quizType, setQuizType] = useState('');
  const [questionCount, setQuestionCount] = useState(5);
  const [difficulty, setDifficulty] = useState('easy');

  // Handles the quiz type change
  const handleQuizTypeChange = (event) => {
    setQuizType(event.target.value);
  };

  // Handles the question count change
  const handleQuestionCountChange = (event) => {
    setQuestionCount(event.target.value);
  };

  // Handles the difficulty level change
  const handleDifficultyChange = (event) => {
    setDifficulty(event.target.value);
  };

  // Submitting the quiz configuration
  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Quiz Type: ${quizType}, Questions: ${questionCount}, Difficulty: ${difficulty}`);
    // In practice, here, you'd make an API call to get the questions based on these inputs.
  };

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6">Create Your Custom Quiz</h1>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <label htmlFor="quiz-type" className="block text-lg font-semibold">Select Quiz Type:</label>
          <select
            id="quiz-type"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={quizType}
            onChange={handleQuizTypeChange}
            required
          >
            <option value="">Select Quiz Type</option>
            <option value="multiple-choice">Multiple Choice</option>
            <option value="true-false">True/False</option>
            <option value="fill-in-the-blank">Fill in the Blank</option>
            <option value="short-answer">Short Answer</option>
            <option value="matching">Matching</option>
          </select>
        </div>

        <div className="space-y-2">
          <label htmlFor="question-count" className="block text-lg font-semibold">Number of Questions:</label>
          <input
            type="number"
            id="question-count"
            className="w-full p-2 border border-gray-300 rounded-md"
            min="1"
            value={questionCount}
            onChange={handleQuestionCountChange}
          />
        </div>

        <div className="space-y-2">
          <label htmlFor="difficulty" className="block text-lg font-semibold">Select Difficulty Level:</label>
          <select
            id="difficulty"
            className="w-full p-2 border border-gray-300 rounded-md"
            value={difficulty}
            onChange={handleDifficultyChange}
            required
          >
            <option value="easy">Easy</option>
            <option value="medium">Medium</option>
            <option value="hard">Hard</option>
          </select>
        </div>

        <button
          type="submit"
          className="bg-blue-600 text-white py-2 px-4 rounded-md mt-4"
        >
          Generate Quiz
        </button>
      </form>
    </div>
  );
};

export default QuizConfigPage;
